/// Create a `AdaptiveCycle` indicator.
///
/// Returns `NULL` on invalid parameters; release with `wickra_adaptive_cycle_free`.
#[no_mangle]
pub extern "C" fn wickra_adaptive_cycle_new() -> *mut AdaptiveCycle {
    Box::into_raw(Box::new(AdaptiveCycle::new()))
}

/// Feed one value; returns the output, or `NaN` during warmup / on a `NULL` handle.
///
/// # Safety
/// `handle` must be a valid pointer from `wickra_adaptive_cycle_new` (not freed), or `NULL`.
#[no_mangle]
pub unsafe extern "C" fn wickra_adaptive_cycle_update(
    handle: *mut AdaptiveCycle,
    value: f64,
) -> f64 {
    match handle.as_mut() {
        Some(ind) => ind.update(value).unwrap_or(f64::NAN),
        None => f64::NAN,
    }
}

/// Run over `input[0..n]`, writing one output per input into `out[0..n]` (`NaN` at warmup).
///
/// # Safety
/// `handle` valid (from `wickra_adaptive_cycle_new`, not freed); `input`/`out` cover `n` `double`s.
#[no_mangle]
pub unsafe extern "C" fn wickra_adaptive_cycle_batch(
    handle: *mut AdaptiveCycle,
    input: *const f64,
    out: *mut f64,
    n: usize,
) {
    if handle.is_null() || input.is_null() || out.is_null() {
        return;
    }
    let ind = &mut *handle;
    let inputs = slice::from_raw_parts(input, n);
    let outputs = slice::from_raw_parts_mut(out, n);
    ind.batch_nan_into(inputs, outputs);
}

/// Opt-in fast batch over `input[0..n]` into `out[0..n]`: an indicator with a
