/// `handle` must be a valid pointer from `wickra_hammer_new` (not freed), or `NULL`.
#[no_mangle]
pub unsafe extern "C" fn wickra_hammer_update(
    handle: *mut Hammer,
    open: f64,
    high: f64,
    low: f64,
    close: f64,
    volume: f64,
    timestamp: i64,
) -> f64 {
    let Some(ind) = handle.as_mut() else {
        return f64::NAN;
    };
    match Candle::new(open, high, low, close, volume, timestamp) {
        Ok(candle) => ind.update(candle).unwrap_or(f64::NAN),
        Err(_) => f64::NAN,
    }
}

/// Run over the OHLCV series (`open/high/low/close/volume/timestamp[0..n]`) into
/// `out[0..n]` (`NaN` at warmup or on an invalid candle).
///
/// # Safety
/// `handle` valid (from `wickra_hammer_new`, not freed); every input pointer and `out`
/// cover `n` elements.
#[no_mangle]
pub unsafe extern "C" fn wickra_hammer_batch(
    handle: *mut Hammer,
    open: *const f64,
    high: *const f64,
    low: *const f64,
    close: *const f64,
    volume: *const f64,
    timestamp: *const i64,
    out: *mut f64,
    n: usize,
) {
    if handle.is_null()
        || open.is_null()
        || high.is_null()
        || low.is_null()
        || close.is_null()
        || volume.is_null()
        || timestamp.is_null()
        || out.is_null()
    {
        return;
    }
    let ind = &mut *handle;
    let opens = slice::from_raw_parts(open, n);
    let highs = slice::from_raw_parts(high, n);
    let lows = slice::from_raw_parts(low, n);
    let closes = slice::from_raw_parts(close, n);
    let volumes = slice::from_raw_parts(volume, n);
    let timestamps = slice::from_raw_parts(timestamp, n);
    let outputs = slice::from_raw_parts_mut(out, n);
    for (idx, slot) in outputs.iter_mut().enumerate() {
        *slot = match Candle::new(
            opens[idx],
            highs[idx],
            lows[idx],
            closes[idx],
            volumes[idx],
            timestamps[idx],
        ) {
            Ok(candle) => ind.update(candle).unwrap_or(f64::NAN),
            Err(_) => f64::NAN,
        };
    }
}

