///
/// Returns `NULL` on invalid parameters; release with `wickra_realized_spread_free`.
#[no_mangle]
pub extern "C" fn wickra_realized_spread_new(horizon: usize) -> *mut RealizedSpread {
    match RealizedSpread::new(horizon) {
        Ok(ind) => Box::into_raw(Box::new(ind)),
        Err(_) => ptr::null_mut(),
    }
}

/// Feed one trade with the prevailing mid price; returns the output, or `NaN` during
/// warmup / on a `NULL` handle / if the trade or mid is invalid.
///
/// # Safety
/// `handle` must be a valid pointer from `wickra_realized_spread_new` (not freed), or `NULL`.
#[no_mangle]
pub unsafe extern "C" fn wickra_realized_spread_update(
    handle: *mut RealizedSpread,
    price: f64,
    size: f64,
    is_buy: bool,
    timestamp: i64,
    mid: f64,
) -> f64 {
    let Some(ind) = handle.as_mut() else {
        return f64::NAN;
    };
    let side = if is_buy { Side::Buy } else { Side::Sell };
    let Ok(trade) = Trade::new(price, size, side, timestamp) else {
        return f64::NAN;
    };
    match TradeQuote::new(trade, mid) {
        Ok(quote) => ind.update(quote).unwrap_or(f64::NAN),
        Err(_) => f64::NAN,
    }
}

/// Run over the trade series with the prevailing mid price into `out[0..n]`
/// (`NaN` at warmup or on an invalid trade or mid).
///
/// # Safety
/// `handle` valid (from `wickra_realized_spread_new`, not freed); every input pointer and `out`
/// cover `n` elements.
#[no_mangle]
pub unsafe extern "C" fn wickra_realized_spread_batch(
    handle: *mut RealizedSpread,
    price: *const f64,
    size: *const f64,
    is_buy: *const bool,
    timestamp: *const i64,
    mid: *const f64,
    out: *mut f64,
    n: usize,
) {
    if handle.is_null()
        || price.is_null()
        || size.is_null()
        || is_buy.is_null()
        || timestamp.is_null()
        || mid.is_null()
        || out.is_null()
    {
        return;
    }
    let ind = &mut *handle;
    let prices = slice::from_raw_parts(price, n);
    let sizes = slice::from_raw_parts(size, n);
    let sides = slice::from_raw_parts(is_buy, n);
    let stamps = slice::from_raw_parts(timestamp, n);
    let mids = slice::from_raw_parts(mid, n);
    let outputs = slice::from_raw_parts_mut(out, n);
    for (i, slot) in outputs.iter_mut().enumerate() {
        let side = if sides[i] { Side::Buy } else { Side::Sell };
        let Ok(trade) = Trade::new(prices[i], sizes[i], side, stamps[i]) else {
            *slot = f64::NAN;
            continue;
        };
        *slot = match TradeQuote::new(trade, mids[i]) {
            Ok(quote) => ind.update(quote).unwrap_or(f64::NAN),
            Err(_) => f64::NAN,
        };
    }
}

