/// Feed one input; on `true` the freshly computed multi-field output is written to
/// `*out`. Returns `false` during warmup, on a `NULL` handle / `out`, or on invalid input.
///
/// # Safety
/// `handle` (from `wickra_aroon_new`, not freed) and `out` must be valid or `NULL`.
#[no_mangle]
pub unsafe extern "C" fn wickra_aroon_update(
    handle: *mut Aroon,
    open: f64,
    high: f64,
    low: f64,
    close: f64,
    volume: f64,
    timestamp: i64,
    out: *mut WickraAroonOutput,
) -> bool {
    let Some(ind) = handle.as_mut() else {
        return false;
    };
    if out.is_null() {
        return false;
    }
    let Ok(input) = Candle::new(open, high, low, close, volume, timestamp) else {
        return false;
    };
    match ind.update(input) {
        Some(out_val) => {
            *out = WickraAroonOutput {
                up: out_val.up,
                down: out_val.down,
            };
            true
        }
        None => false,
    }
}

/// Run over the input series, writing one `WickraAroonOutput` per input into
/// `out[0..n]`. A row the indicator did not produce -- warmup, or an input it
/// rejected -- is written with every field set to `NaN`, which is how a caller
/// tells the two apart from a real value.
///
/// # Safety
/// `handle` valid (from `wickra_aroon_new`, not freed); every input pointer covers
/// `n` elements and `out` covers `n` `WickraAroonOutput` values.
#[no_mangle]
pub unsafe extern "C" fn wickra_aroon_batch(
    handle: *mut Aroon,
    open: *const f64,
    high: *const f64,
    low: *const f64,
    close: *const f64,
    volume: *const f64,
    timestamp: *const i64,
    out: *mut WickraAroonOutput,
    n: usize,
) {
    if handle.is_null()
        || open.is_null()
        || high.is_null()
        || low.is_null()
        || close.is_null()
        || volume.is_null()
        || timestamp.is_null()
        || out.is_null()
    {
        return;
    }
    let ind = &mut *handle;
    let opens = slice::from_raw_parts(open, n);
    let highs = slice::from_raw_parts(high, n);
    let lows = slice::from_raw_parts(low, n);
    let closes = slice::from_raw_parts(close, n);
    let volumes = slice::from_raw_parts(volume, n);
    let timestamps = slice::from_raw_parts(timestamp, n);
    let outputs = slice::from_raw_parts_mut(out, n);
    for (i, slot) in outputs.iter_mut().enumerate() {
        *slot = WickraAroonOutput {
            up: f64::NAN,
            down: f64::NAN,
        };
        let Ok(input) = Candle::new(
            opens[i],
            highs[i],
            lows[i],
            closes[i],
            volumes[i],
            timestamps[i],
        ) else {
            continue;
        };
        if let Some(out_val) = ind.update(input) {
            *slot = WickraAroonOutput {
                up: out_val.up,
                down: out_val.down,
            };
        }
    }
}

