/// Feed one input. On warmup / `NULL` handle / invalid input returns `-1`. Otherwise
/// returns the length of the `counts` payload and writes up to `cap` of its values
/// into `values` (enlarge `cap` if the return exceeds it); the scalar fields are written
/// to `*scalars` when non-`NULL`.
///
/// # Safety
/// `handle` (from `wickra_tpo_profile_new`, not freed), `scalars` and `values` must be valid
/// or `NULL`; when non-`NULL`, `values` must cover `cap` `double`s.
#[no_mangle]
pub unsafe extern "C" fn wickra_tpo_profile_update(
    handle: *mut TpoProfile,
    open: f64,
    high: f64,
    low: f64,
    close: f64,
    volume: f64,
    timestamp: i64,
    scalars: *mut WickraTpoProfileOutputScalars,
    values: *mut f64,
    cap: usize,
) -> isize {
    let Some(ind) = handle.as_mut() else {
        return -1;
    };
    let Ok(input) = Candle::new(open, high, low, close, volume, timestamp) else {
        return -1;
    };
    match ind.update(input) {
        Some(out_val) => {
            if !scalars.is_null() {
                *scalars = WickraTpoProfileOutputScalars {
                    price_low: out_val.price_low,
                    price_high: out_val.price_high,
                };
            }
            if !values.is_null() {
                let slots = slice::from_raw_parts_mut(values, cap);
                for (slot, &v) in slots.iter_mut().zip(&out_val.counts) {
                    *slot = v;
                }
            }
            isize::try_from(out_val.counts.len()).unwrap_or(isize::MAX)
        }
        None => -1,
    }
}

/// How many values every emitted profile carries. Fixed for the lifetime of the
/// handle, so a caller can size a buffer once instead of guessing. Returns `0`
/// if `handle` is `NULL`.
///
/// # Safety
/// `handle` must be valid (from `wickra_tpo_profile_new`, not freed), or `NULL`.
#[no_mangle]
pub unsafe extern "C" fn wickra_tpo_profile_width(handle: *mut TpoProfile) -> usize {
    match handle.as_ref() {
        Some(ind) => ind.width(),
        None => 0,
    }
}

/// Run over the input series, writing one profile per input into `values` as a
/// flat `n * width` block. A row the indicator did not produce -- warmup, or an
/// input it rejected -- is filled with `NaN`. `width` is the payload length the
/// constructor fixes; a shorter payload leaves the rest of its row `NaN`.
/// The scalar fields of each row are written to `scalars[i]` when `scalars`
/// is non-`NULL`; a row the indicator did not produce is filled with `NaN`.
///
/// # Safety
/// `handle` valid (from `wickra_tpo_profile_new`, not freed) or `NULL`; every input
/// pointer covers `n` elements, `values` covers `n * width` `double`s, and `scalars` covers `n` `WickraTpoProfileOutputScalars`.
#[no_mangle]
pub unsafe extern "C" fn wickra_tpo_profile_batch(
    handle: *mut TpoProfile,
    open: *const f64,
    high: *const f64,
    low: *const f64,
    close: *const f64,
    volume: *const f64,
    timestamp: *const i64,
    scalars: *mut WickraTpoProfileOutputScalars,
    values: *mut f64,
    width: usize,
    n: usize,
) {
    let Some(ind) = handle.as_mut() else {
        return;
    };
    if open.is_null()
        || high.is_null()
        || low.is_null()
        || close.is_null()
        || volume.is_null()
        || timestamp.is_null()
        || values.is_null()
    {
        return;
    }
    let opens = slice::from_raw_parts(open, n);
    let highs = slice::from_raw_parts(high, n);
    let lows = slice::from_raw_parts(low, n);
    let closes = slice::from_raw_parts(close, n);
    let volumes = slice::from_raw_parts(volume, n);
    let timestamps = slice::from_raw_parts(timestamp, n);
    let rows = slice::from_raw_parts_mut(values, n * width);
    for slot in rows.iter_mut() {
        *slot = f64::NAN;
    }
    let scalar_rows = if scalars.is_null() {
        None
    } else {
        Some(slice::from_raw_parts_mut(scalars, n))
    };
    let mut scalar_rows = scalar_rows;
    if let Some(rows) = scalar_rows.as_mut() {
        for row in rows.iter_mut() {
            *row = WickraTpoProfileOutputScalars {
                price_low: f64::NAN,
                price_high: f64::NAN,
            };
        }
    }
    for i in 0..n {
        let Ok(input) = Candle::new(
            opens[i],
            highs[i],
            lows[i],
            closes[i],
            volumes[i],
            timestamps[i],
        ) else {
            continue;
        };
        let Some(out_val) = ind.update(input) else {
            continue;
        };
        if let Some(rows) = scalar_rows.as_mut() {
            rows[i] = WickraTpoProfileOutputScalars {
                price_low: out_val.price_low,
                price_high: out_val.price_high,
            };
        }
        let row = &mut rows[i * width..(i + 1) * width];
        for (slot, &v) in row.iter_mut().zip(&out_val.counts) {
            *slot = v;
        }
    }
}

