/// the total number completed on this candle (0, 1, or several). Any that did not
/// fit are buffered -- retrieve them with `wickra_tick_bars_drain`, which is the only
/// way to get them and must be called before the next `update`. Returns 0 on a
/// `NULL` handle or an invalid candle.
///
/// # Safety
/// `handle` (from `wickra_tick_bars_new`, not freed) and `out` must be valid or `NULL`; when
/// non-`NULL`, `out` must cover `cap` `WickraTickBar` elements.
#[no_mangle]
pub unsafe extern "C" fn wickra_tick_bars_update(
    handle: *mut TickBars,
    open: f64,
    high: f64,
    low: f64,
    close: f64,
    volume: f64,
    timestamp: i64,
    out: *mut WickraTickBar,
    cap: usize,
) -> usize {
    let Some(builder) = handle.as_mut() else {
        return 0;
    };
    let Ok(candle) = Candle::new(open, high, low, close, volume, timestamp) else {
        return 0;
    };
    let bars = builder.inner.update(candle);
    let total = bars.len();
    let mut rest = bars.into_iter();
    if !out.is_null() {
        let slots = slice::from_raw_parts_mut(out, cap);
        for (slot, bar) in slots.iter_mut().zip(rest.by_ref()) {
            *slot = WickraTickBar {
                open: bar.open,
                high: bar.high,
                low: bar.low,
                close: bar.close,
                volume: bar.volume,
            };
        }
    }
    builder.pending = rest.collect();
    total
}

/// Copy up to `cap` bars the last `update` could not fit into `out`, remove them
/// from the buffer, and return the number written. Returns 0 on a `NULL` handle /
/// `out`, or when nothing is buffered.
///
/// # Safety
/// `handle` (from `wickra_tick_bars_new`, not freed) and `out` must be valid or `NULL`;
/// when non-`NULL`, `out` must cover `cap` `WickraTickBar` elements.
#[no_mangle]
pub unsafe extern "C" fn wickra_tick_bars_drain(
    handle: *mut TickBars,
    out: *mut WickraTickBar,
    cap: usize,
) -> usize {
    let Some(builder) = handle.as_mut() else {
        return 0;
    };
    if out.is_null() {
        return 0;
    }
    let count = builder.pending.len().min(cap);
    let slots = slice::from_raw_parts_mut(out, count);
    for (slot, bar) in slots.iter_mut().zip(builder.pending.drain(..count)) {
        *slot = WickraTickBar {
            open: bar.open,
            high: bar.high,
            low: bar.low,
            close: bar.close,
            volume: bar.volume,
        };
    }
    count
}

/// Feed `n` OHLCV candles and buffer every bar they complete. Returns the total,
/// or 0 on a `NULL` handle or a `NULL` input pointer. Retrieve the bars with
/// `wickra_tick_bars_drain`, which is the only way to get them; an invalid candle
/// is skipped rather than aborting the run.
///
/// # Safety
/// `handle` valid (from `wickra_tick_bars_new`, not freed) or `NULL`; every input
/// pointer covers `n` elements.
#[no_mangle]
pub unsafe extern "C" fn wickra_tick_bars_batch(
    handle: *mut TickBars,
    open: *const f64,
    high: *const f64,
    low: *const f64,
    close: *const f64,
    volume: *const f64,
    timestamp: *const i64,
    n: usize,
) -> usize {
    let Some(builder) = handle.as_mut() else {
        return 0;
    };
    if open.is_null()
        || high.is_null()
        || low.is_null()
        || close.is_null()
        || volume.is_null()
        || timestamp.is_null()
    {
        return 0;
    }
    let opens = slice::from_raw_parts(open, n);
    let highs = slice::from_raw_parts(high, n);
    let lows = slice::from_raw_parts(low, n);
    let closes = slice::from_raw_parts(close, n);
    let volumes = slice::from_raw_parts(volume, n);
    let stamps = slice::from_raw_parts(timestamp, n);
    builder.pending.clear();
    for i in 0..n {
        let Ok(candle) = Candle::new(
            opens[i], highs[i], lows[i], closes[i], volumes[i], stamps[i],
        ) else {
            continue;
        };
        builder.pending.extend(builder.inner.update(candle));
    }
    builder.pending.len()
}

/// Canonical indicator name as a NUL-terminated C string with `'static` lifetime
/// (cached on first call). Returns `NULL` if `handle` is `NULL`.
///
/// # Safety
/// `handle` must be valid (from `wickra_tick_bars_new`, not freed), or `NULL`.
#[no_mangle]
pub unsafe extern "C" fn wickra_tick_bars_name(handle: *mut TickBars) -> *const c_char {
    match handle.as_ref() {
        Some(ind) => {
            static NAME: OnceLock<CString> = OnceLock::new();
            NAME.get_or_init(|| {
                CString::new(ind.inner.name()).expect("indicator name has no interior NUL")
            })
            .as_ptr()
        }
        None => ptr::null(),
    }
}

/// Reset all internal state. No-op if `handle` is `NULL`.
