#[no_mangle]
pub unsafe extern "C" fn wickra_tick_bars_reset(handle: *mut TickBars) {
    if let Some(ind) = handle.as_mut() {
        ind.inner.reset();
    }
}

/// Destroy a handle created by `wickra_tick_bars_new`. No-op if `handle` is `NULL`.
